function productDefaults(){defaults({gap:15,editId:'',day:'周六'})}
function productRender(){const sorted=state.tasks.filter(x=>x.day===p.day).sort((a,b)=>a.start.localeCompare(b.start));let prev=8*60;const free=[];for(const x of sorted){const start=mins(x.start),end=mins(x.end);if(start-prev>=30)free.push([prev,start]);prev=Math.max(prev,end+p.gap)}if(prev<20*60)free.push([prev,20*60]);const edit=state.tasks.find(x=>x.id===p.editId);put(`<div class="grid"><div>${box('空闲时间雷达',`<form id="gap-form" class="fields">${select('查看哪天','day',['周六','周日'],p.day)}${field('活动后留白 / 分钟','gap','number',p.gap,'required min="0" max="120"')}<button>更新时间规则</button></form>${rows(free,r=>`<div class="item"><strong>${humanTime(r[0])} — ${humanTime(r[1])}</strong><span>${r[1]-r[0]} 分钟空闲</span></div>`)}${note('在 08:00—20:00 内查找至少 30 分钟的空档；已有活动之后预留休息时间。')}`)}${box('快速调整活动',rows(sorted,x=>`<div class="item"><div>${esc(x.name)}<p>${x.start}—${x.end} · ${x.priority}优先级</p></div><button data-edit="${x.id}" class="small">编辑</button></div>`)+btn('复制本日日程到另一日','copy-day',''))}</div><div>${edit?box('修改活动安排',`<form id="edit-task" class="stack">${field('名称','name','text',edit.name,'required maxlength="60"')}<div class="fields">${select('星期','day',['周六','周日'],edit.day)}${select('优先级','priority',['高','中','低'],edit.priority)}${field('开始','start','time',edit.start,'required')}${field('结束','end','time',edit.end,'required')}</div><button class="primary">保存安排</button></form>`):box('安排建议',`<p>先留出休息与活动间隔，再安排重要任务。空档过小时，尝试缩短或移动低优先级活动。</p>`,'tint')}${box('日程导出',btn('导出周末计划 CSV','schedule-csv',''))}</div></div>`);form('gap-form',v=>{p.gap=+v.gap;p.day=v.day;commit()});deleteButtons('edit',id=>{p.editId=id;commit()});form('edit-task',v=>{if(mins(v.end)<=mins(v.start))return toast('结束时间应晚于开始时间');Object.assign(edit,v);p.editId='';commit()});on('copy-day',()=>{const target=p.day==='周六'?'周日':'周六';if(state.tasks.some(x=>x.day===target))return toast('目标日已有活动；先清理目标日，避免重复覆盖');state.tasks.push(...sorted.map(x=>({...clone(x),day:target,id:uid(),done:false})));commit()});on('schedule-csv',()=>exportCSV('周末计划.csv',['星期','开始','结束','活动','优先级','完成'],state.tasks.map(x=>[x.day,x.start,x.end,x.name,x.priority,x.done?'是':'否'])))}
